export const XRAY_STATUSES = ["PASS", "FAIL", "TODO"];
export const DEFAULT_STATUSES = {
    passed: "PASS",
    failed: "FAIL",
    broken: "FAIL",
    skipped: "TODO",
    unknown: "TODO",
};
const ISSUE_KEY_PATTERN = /[A-Z][A-Z0-9_]*-\d+/;
const EXACT_ISSUE_KEY_PATTERN = new RegExp(`^${ISSUE_KEY_PATTERN.source}$`);
export const isXrayStatus = (value) => XRAY_STATUSES.includes(value);
export const splitList = (value) => uniq(value.split(","));
export const uniq = (values) => [...new Set(values.map((value) => value.trim()).filter(Boolean))];
export const escapeWikiLinkText = (text) => text.replace(/[\\[\]|]/g, "\\$&");
export const getTestKey = (link) => {
    if (link.type !== "tms") {
        return undefined;
    }
    const name = link.name?.trim();
    return name && EXACT_ISSUE_KEY_PATTERN.test(name) ? name : link.url.match(ISSUE_KEY_PATTERN)?.[0];
};
export const mergeStatus = (current, next) => {
    if (current === "FAIL" || next === "FAIL") {
        return "FAIL";
    }
    if (current === "PASS" || next === "PASS") {
        return "PASS";
    }
    return "TODO";
};
export const collectStatuses = (results, statuses) => {
    const result = new Map();
    for (const tr of results) {
        for (const link of tr.links) {
            const key = getTestKey(link);
            if (key) {
                result.set(key, mergeStatus(result.get(key), statuses[tr.status]));
            }
        }
    }
    return result;
};
